func TestSelectWhySummary_PrefersGeneratedSummaryThenIntentThenCommitSubject(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name          string
		summary       *checkpoint.Summary
		commitSubject string
		want          string
		wantFallback  bool
	}{
		{
			name: "generated summary wins",
			summary: &checkpoint.Summary{
				Outcome: "Saved generated summary",
				Intent:  "Fallback intent",
			},
			commitSubject: "Commit subject",
			want:          "Saved generated summary",
			wantFallback:  false,
		},
		{
			name: "intent falls back when generated summary missing",
			summary: &checkpoint.Summary{
				Intent: "User intent",
			},
			commitSubject: "Commit subject",
			want:          "User intent",
			wantFallback:  true,
		},
		{
			name:          "commit subject is last resort",
			summary:       nil,
			commitSubject: "Commit subject",
			want:          "Commit subject",
			wantFallback:  true,
		},
	}

	for _, tt := range tests {
		tt := tt
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()

			got, fallback := selectWhySummary(tt.summary, tt.commitSubject)
			if got != tt.want {
				t.Fatalf("summary = %q, want %q", got, tt.want)
			}
			if fallback != tt.wantFallback {
				t.Fatalf("fallback = %v, want %v", fallback, tt.wantFallback)
			}
		})
	}
}

func TestEnrichWhyBlocks_LeavesGitOnlyRowsBlank(t *testing.T) {
	repoDir := t.TempDir()
	testutil.InitRepo(t, repoDir)
	testutil.WriteFile(t, repoDir, "main.go", "package main\n")
	testutil.GitAdd(t, repoDir, "main.go")
	testutil.GitCommit(t, repoDir, "Improve CLI error handling")

	t.Chdir(repoDir)

	got, err := enrichWhyBlocks(context.Background(), []whyBlock{{Commit: whyCommitInfo{Hash: testutil.GetHeadHash(t, repoDir)}}})
	if err != nil {
		t.Fatalf("enrich error: %v", err)
	}
	if got[0].Entire != nil {
		t.Fatal("expected no Entire enrichment")
	}
}

